const e=JSON.parse(`{"back":"Zurück","continue":"Weiter","step_of":"{current} von {total}","welcome":{"title":"Willkommen","lede":"Zuerst ein kurzer Blick darauf, was {name} ist und wie es funktioniert. Danach richten wir es direkt hier in der App ein: einen API-Schlüssel, ein Abo für deine Agents und dein Weckwort.","language":"Sprache","lang_en":"English","lang_de":"Deutsch","lang_es":"Español","start":"Los geht's"},"how":{"title":"So funktioniert {name}","lede":"Ein Assistent, mit dem du sprichst. Dahinter: ein Gehirn, Werkzeuge, ein Team aus Agents und ein Gedächtnis.","next":"Weiter","prev":"Zurück","skip":"Erklärung überspringen","finish":"Verstanden, jetzt einrichten","chapter_of":"{current} / {total}","chapters_label":"Kapitel","map_label":"Wie die Teile deines Assistenten zusammenhängen","journey_pick":"Wähle eine Beispiel-Anfrage","journey_replay":"Nochmal abspielen","nodes":{"center":"{name}","you":"Du","you_sub":"Stimme, Chat, Handy","brain":"Gehirn","brain_sub":"Das KI-Modell","tools":"Werkzeuge","tools_sub":"Computer, Apps, Web","agents":"Agents","agents_sub":"Team für große Jobs","memory":"Gedächtnis","memory_sub":"Wiki und Profil","results":"Ergebnisse","results_sub":"Antworten und Dateien","safety":"Sicherheitscheck"},"chapters":{"intro":{"title":"Ein Assistent für alles","say":"Hi, ich bin Gigi! {name} ist nicht einfach noch ein Chatbot. Es ist EIN Assistent, der für dich an deinem Computer arbeitet. Du sprichst immer nur mit {name}: Es entscheidet, was zu tun ist und wer es erledigt.","p1":"Kein Hin und Her zwischen Apps und KI-Tools. Du sagst einmal, was du willst.","p2":"{name} denkt nach, benutzt deinen Computer und deine Apps und gibt große Aufgaben an Helfer-Agents ab.","p3":"Alles kommt an einer Stelle zu dir zurück: laut gesprochen, im Chat oder als fertige Datei."},"you":{"title":"Sprich mit ihm, wie du willst","say":"Sprechen, tippen oder vom Handy schreiben. Jeder Weg führt zum selben {name}, mit demselben Gedächtnis.","p1":"Stimme: Sag dein Weckwort oder drück die Anruf-Tastenkombination und sprich einfach los. {name} antwortet laut.","p2":"Chat: Tipp in der App. Jedes Gespräch wird unter „Letzte Chats“ gespeichert.","p3":"Unterwegs: Verbinde Telegram und schreib {name} vom Handy. Das Diktat tippt, was du sagst, in jede andere App."},"brain":{"title":"Das Gehirn: ein KI-Modell deiner Wahl","say":"Zum Nachdenken nutzt {name} ein KI-Modell: von OpenAI, Google Gemini, Anthropic Claude, OpenRouter und anderen oder eines, das auf deinem eigenen Computer läuft. Du entscheidest.","p1":"Ein Schlüssel reicht. Du fügst ihn im nächsten Schritt hinzu und kannst das Modell jederzeit wechseln.","p2":"Für Agents spart ein Abo, das du schon bezahlst (Claude oder ChatGPT), die Kosten pro Aufruf.","p3":"Fällt ein Anbieter aus, wechselt {name} zu einem anderen, den du verbunden hast, statt stehen zu bleiben."},"tools":{"title":"Werkzeuge: seine Hände","say":"Kleine Aufgaben erledigt {name} selbst, sofort, während ihr redet. Genau das sind Werkzeuge: seine Hände an deinem Computer und in deinen Apps.","p1":"Dein Computer: Apps und Webseiten öffnen, am Bildschirm klicken und tippen, auf den Bildschirm schauen, Dateien lesen und schreiben, Befehle ausführen.","p2":"Deine Apps und Dienste: E-Mail, Kalender, Smart Home und mehr, verbunden als Plugins oder MCP aus dem Marketplace.","p3":"Skills: Bring ihm einen Ablauf einmal bei, und es wiederholt ihn, wann immer du willst."},"agents":{"title":"Agents: ein Team für große Aufgaben","say":"Dauert eine Aufgabe länger, etwa eine Recherche, ein Bericht, eine Webseite oder Code, gibt {name} sie an einen Agent ab. Du redest weiter, der Agent arbeitet im Hintergrund.","p1":"Agents wohnen im Bereich Agents. Schau ihnen bei der Arbeit zu, chatte mit einem oder gib ihm direkt einen Auftrag.","p2":"Ein Prüfer kontrolliert die Arbeit des Agents, bevor das Ergebnis bei dir ankommt.","p3":"Coding-Agents wie Claude Code und Codex laufen nebeneinander in der Agentic IDE, an deinen eigenen Projekten. Agents können auch Routinen nach Zeitplan ausführen."},"memory":{"title":"Gedächtnis: es lernt dich kennen","say":"{name} merkt sich, was wichtig ist: was du ihm erzählt hast, was du magst, die Menschen und Projekte in deinem Leben.","p1":"Das Wiki enthält Notizen, die {name} lesen, schreiben und zitieren kann. Du kannst jede Seite öffnen und bearbeiten.","p2":"Dein Profil sammelt, was es über dich weiß, damit du dich nie wiederholen musst.","p3":"Chats, Notizen und Dateien liegen auf deinem Computer. Nur was ein Modell für eine Antwort braucht, geht an den Anbieter deiner Wahl."},"safety":{"title":"Du behältst die Kontrolle","say":"Bevor {name} etwas tut, prüft es ein Sicherheitscheck. Harmloses passiert einfach. Alles mit echten Folgen wartet auf dein Ja.","p1":"Vier Stufen: sicher (läuft), beobachtet (läuft und wird protokolliert), fragen (wartet auf dein OK), gesperrt (läuft nie).","p2":"Eine E-Mail senden, Dateien löschen oder jemanden anrufen fragt dich vorher und zeigt dir genau, was passieren wird.","p3":"Schlüssel bleiben im Schlüsselbund deines Systems. Sag oder tippe nie einen Schlüssel in den Chat: {name} nimmt dort keinen an."},"journey":{"title":"Probier's aus: folge einer Anfrage","say":"Wähle unten eine Anfrage und sieh zu, welchen Weg sie durch {name} nimmt."},"app":{"title":"Wo du alles in der App findest","say":"Alles, was du gerade gesehen hast, hat links in der Seitenleiste seinen eigenen Platz. Jetzt richten wir zusammen das Gehirn ein, das dauert etwa zwei Minuten."}},"journeys":{"e1":{"label":"Was steht morgen in meinem Kalender?","s1":"Du fragst per Stimme.","s2":"Hört dich und versteht, was du willst.","s3":"Entscheidet: Dafür brauche ich deinen Kalender.","s4":"Liest deinen Kalender über die verbundene App, ein schneller Werkzeug-Aufruf.","s5":"Die Antwort wird nach wenigen Sekunden laut gesprochen."},"e2":{"label":"Bau eine Webseite für meine Bäckerei","s1":"Du fragst im Chat.","s2":"Erkennt eine große Aufgabe.","s3":"Plant die Arbeit und wählt den passenden Helfer.","s4":"Ein Agent baut die Seite im Hintergrund, während du weiterredest; ein Prüfer kontrolliert sie.","s5":"Die fertige Seite erscheint in Artifacts und in deinem Chat."},"e3":{"label":"Merk dir: Annas Geburtstag ist am 3. Mai","s1":"Du erwähnst es nebenbei.","s2":"Merkt: Das ist es wert, behalten zu werden.","s3":"Schreibt es ins Wiki, auf Annas Seite.","s4":"Wenn du das nächste Mal nach Anna fragst, weiß {name} es."},"e4":{"label":"Schreib dem Team, dass ich mich verspäte","s1":"Du sagst es im Rausgehen.","s2":"Versteht: eine E-Mail an dein Team.","s3":"Schreibt die E-Mail.","s4":"Senden ist eine echte Aktion, also zeigt dir {name} die E-Mail und wartet auf dein Ja.","s5":"Erst nach deinem OK sendet es über dein verbundenes Postfach.","s6":"{name} bestätigt, dass sie raus ist."}},"app":{"chats":"Chats","chats_sub":"Mit {name} sprechen und tippen; jedes Gespräch wird gespeichert.","agents":"Agents","agents_sub":"Dein Team bei der Arbeit: Agents anlegen, beauftragen, zuschauen.","voice":"Stimme","voice_sub":"Diktat in jede App, deine Wortliste, gesprochene Kurzbefehle.","artifacts":"Artifacts","artifacts_sub":"Seiten, Bilder und Berichte, die {name} für dich gemacht hat.","ide":"Agentic IDE","ide_sub":"Coding-Agents in echten Terminals, an deinen Projekten.","plugins":"Plugins","plugins_sub":"Apps verbinden und Skills hinzufügen; mehr im Marketplace.","settings":"Einstellungen","settings_sub":"API-Schlüssel, Gedächtnis, Kosten und dein Profil."}},"keys":{"title":"Einen API-Schlüssel eintragen","lede":"Dein Assistent braucht einen KI-Schlüssel, um zu denken und zu sprechen; ohne ihn bleiben Chat und Sprache aus. Das ist die Seite API-Keys: Füge einen Schlüssel in eine Anbieter-Karte ein und speichere ihn. Mit OpenAI oder Gemini reicht ein einziger Schlüssel für Live-Sprache.","waiting":"Warte auf einen Schlüssel…","connecting":"Alles wird eingeschaltet…","connected":"Verbunden: {provider}.","present":"Ein Schlüssel ist gespeichert. Du kannst weiter.","partial":"Einige Teile wurden nicht umgestellt ({parts}). Du kannst das später auf dieser Seite beheben.","security":"Schlüssel liegen im Schlüsselbund deines Systems und gehen nur an den Anbieter, den du gewählt hast.","later":"Ich trage später einen Schlüssel ein"},"subscriptions":{"title":"Verbinde ein Abo für deine Agents","lede":"Das ist der Agents-Tab. Melde dich mit einem Abo an, das du schon bezahlst. Wir empfehlen Claude (Pro oder Max) oder ChatGPT (Codex). Klick in der Zeile auf Connect; dein Browser öffnet sich einmal.","waiting":"Noch kein Abo verbunden…","connected":"Verbunden: {names}.","why":"Ein Abo kostet einen festen Monatspreis. So rechnen die größeren Aufgaben deiner Agents nicht pro Aufruf über deinen API-Schlüssel ab.","later":"Ich verbinde später eins"},"permissions":{"title":"Zugriff auf diesem Mac erlauben","lede":"Das sind die Mac-Berechtigungen. Erlaube die, die du möchtest; jede Zeile aktualisiert sich selbst.","note":"Du kannst jederzeit in den Einstellungen zurückkommen. Der Neustart am Ende wendet sie an."},"voice":{"title":"Wähle dein Weckwort","lede":"Tippe hier dein Wort nach „Hey“ ein und speichere es. Das Wort wird auch der Name deines Assistenten. Kein Weckwort? Das Anruf-Kürzel funktioniert immer.","on":"„{phrase}“ ist an. Sag es jederzeit.","off":"Noch kein Weckwort. Bis dahin funktioniert das Anruf-Kürzel.","later":"Überspringen, ich nutze das Anruf-Kürzel"},"ready":{"title":"Alles bereit","lede":"Das ist eingerichtet. Als Nächstes zeigt dir eine kurze Tour die App.","row_brain":"Gehirn","row_agents":"Agents","row_voice":"Aktivierung","no_subscription":"Kein Abo","no_key":"Noch kein Schlüssel","shortcut":"Anruf-Kürzel","autostart":"Bei der Anmeldung starten","no_key_note":"Ohne Schlüssel bleiben Chat und Sprache aus, bis du auf der Seite API-Keys einen einträgst.","preview_note":"Das ist eine Wiederholung, deshalb startet nichts neu.","restart_note":"Nach der Tour startet die App einmal neu (etwa zehn Sekunden), damit alles eingeschaltet ist.","start":"Zeig mir die App"}}`),n={label:"App-Tour",next:"Weiter",finish:"Fertig",skip:"Tour überspringen",step_of:"{current} von {total}",replay_title:"Einrichtung und App-Tour",replay_body:"Erklärt noch einmal, wie {name} funktioniert, führt dich durch die Einrichtung (API-Schlüssel, Abos für Agents, Weckwort) und danach durch den kurzen Rundgang. Nichts startet neu.",replay:"Wiederholen",steps:{voice:"So sprichst du mit {name}. Klick auf die Leiste, sag dein Weckwort oder drück dein Anruf-Kürzel, dann sprich einfach. Die Welle zeigt, wer gerade redet.",new_chat:"Lieber tippen? Hier startest du einen neuen Chat, als Text oder mit Stimme. Jedes Gespräch landet unter Letzte Chats.",agents:"Agenten sind dein Team: Helfer, die größere Aufgaben im Hintergrund übernehmen. Schauen wir rein.",agents_world:"Das ist das Verse, deine Agenten bei der Arbeit. Klick einen an, um mit ihm zu chatten oder ihm eine Aufgabe zu geben. Weiter bringt dich zurück.",voice_hub:"Unter Stimme findest du Diktat in jede App, deine eigene Wortliste und gesprochene Kürzel.",artifacts:"Alles, was {name} erstellt, von Seiten über Bilder bis zu Berichten, liegt unter Artefakte.",ide:"Die Agentic IDE lässt Coding-Agenten nebeneinander in echten Terminals an deinen Projekten arbeiten.",plugins:"Plugins, Skills und MCP verbinden {name} mit deinen Apps. Das Laden-Symbol unten öffnet den Marketplace.",settings:"Hier findest du Einstellungen, API-Schlüssel, Kosten und dein Profil. Die Tour kannst du jederzeit unter Einstellungen → App wiederholen.",done:"Das war die Tour. Du bist startklar: Sprich mit {name}, wann immer du willst."}},i={title:"Erste Schritte",progress:"{done}/{total}",collapse:"Minimieren",close:"Schließen",quest_of:"Schritt {current} von {total}",how_label:"So funktioniert's:",waiting:"Gesendet. Schau in den Chat: {name} ist dran.",next:"Nächster Schritt",finish:"Abschließen",skip:"Diesen überspringen",try:{send:"Für mich senden",voice:"Sprachmodus öffnen",open:"Hinbringen"},show:{memory:"Notizen öffnen",artifact:"Artifacts öffnen",agent:"In Agents ansehen"},replay_title:"Erste Schritte mit {name}",replay:"Starten",replay_body:"Zehn kleine, echte Dinge zum Ausprobieren mit {name}: sprechen, Werkzeuge nutzen, sich etwas merken, etwas bauen, an Agents abgeben. Jedes wird erklärt, nachdem es passiert ist.",finished:{title:"Du kennst jetzt die Grundlagen!",body:"Du hast {done} von {total} ersten Schritten geschafft. Ab jetzt sprichst du einfach mit {name}: Es entscheidet selbst, ob es antwortet, ein Werkzeug nutzt oder einen Agent dazuholt.",close:"Schließen"},quests:{wake:{title:"Weck {name} auf",ask:"Sag dein Weckwort laut, zum Beispiel „Hey {name}“. Oder öffne den Sprachmodus und drück den runden Knopf in der Chatleiste. Dann frag einfach los.",explain:"{name} hört zu. Mehr braucht es nicht: aufwecken und reden wie mit einem Menschen.",how:"Dein Weckwort wird direkt hier auf deinem Computer erkannt. Erst danach geht deine Sprache an das Gehirn, und die Antwort kommt als Stimme zurück."},ask:{title:"Stell deine erste Frage",ask:"Tipp oder sag eine Frage. Probier diese:",prompt:"Was kannst du für mich tun? Nenn mir drei Beispiele aus meinem Alltag.",explain:"Das war der einfachste Weg: Deine Worte gingen an das Gehirn, und es hat direkt geantwortet.",how:"Das Gehirn ist das KI-Modell, das du verbunden hast. Einfache Fragen brauchen keine Werkzeuge, deshalb kommt die Antwort in Sekunden. Jeder Chat wird unter „Letzte Chats“ gespeichert."},tool:{title:"Lass es ein Werkzeug benutzen",ask:"Jetzt bitte um etwas, wofür es seine Hände braucht, nicht nur seinen Kopf:",prompt:"Öffne wikipedia.org in meinem Browser.",explain:"Diesmal hat das Gehirn nicht nur geantwortet: Es hat ein Werkzeug benutzt, um an deinem Computer zu handeln.",how:"Werkzeuge sind die Hände von {name}. Das Gehirn wählt eines, der Sicherheitscheck gibt es frei, und es läuft. Unter jeder Antwort kannst du die Schritte aufklappen und jedes benutzte Werkzeug sehen."},screen:{title:"Lass es auf deinen Bildschirm schauen",ask:"{name} kann deinen Bildschirm sehen, aber nur, wenn du fragst. Probier:",prompt:"Was ist gerade auf meinem Bildschirm? Beschreib es kurz.",explain:"{name} hat einmal auf deinen Bildschirm geschaut und ihn beschrieben.",how:"Ein Blick auf den Bildschirm ist ein einzelnes Foto, nur dann, wenn eine Anfrage es braucht. Es geht wie ein Bild an das Gehirn. Nichts zeichnet deinen Bildschirm im Hintergrund auf."},memory:{title:"Bring ihm etwas bei",ask:"Erzähl {name} etwas, das es sich merken soll:",prompt:"Merk dir, dass meine Lieblingsfarbe Blau ist und dass ich kurze Antworten mag.",explain:"{name} hat das in seinem Gedächtnis gespeichert und nutzt es ab jetzt.",how:"Fakten landen in deinem Wiki und Profil, gespeichert auf deinem Computer. Bevor {name} antwortet, schaut es nach, was es über dich weiß. In den Notizen kannst du alles lesen und bearbeiten."},artifact:{title:"Lass es etwas bauen",ask:"{name} kann fertige Dinge bauen: Seiten, Übersichten, kleine Tools. Sag „Artifact“, um eins anzufordern:",prompt:"Erstelle ein Artifact: eine einseitige Übersicht über die Planeten unseres Sonnensystems, mit je einem spannenden Fakt.",explain:"{name} hat angefangen, die Seite zu bauen. Sobald sie fertig ist, erscheint sie in Artifacts.",how:"Ein Artifact ist eine größere Arbeit, deshalb gibt {name} sie an einen Helfer auf einem starken Modell ab. Der baut eine eigenständige Seite, und Artifacts bewahrt sie auf, damit du sie später wieder öffnen kannst."},agent:{title:"Gib einem Agent eine große Aufgabe",ask:"Für längere Arbeit holt {name} einen Agent dazu. Du kannst weiterreden, während er arbeitet:",prompt:"Recherchiere die drei besten günstigen Laptops gerade und schreib mir einen kurzen Vergleich.",explain:"{name} hat die Aufgabe an einen Agent abgegeben. Er arbeitet im Hintergrund; das Ergebnis kommt in deinen Chat.",how:"{name} bleibt dein einziger Ansprechpartner. Es plant die Aufgabe und startet einen Agent, und ein Prüfer kontrolliert das Ergebnis, bevor es bei dir ankommt. Den Fortschritt siehst du unter Agents."},team:{title:"Lern dein Team kennen",ask:"Agents sind Helfer mit einer eigenen Rolle. Öffne den Bereich Agents, um sie kennenzulernen.",explain:"Hier wohnen und arbeiten deine Agents.",how:"Leg einen eigenen Agent an, mit eigener Rolle, eigenem Modell und eigenen Anweisungen, zum Beispiel einen Rechercheur oder eine Texterin. Klick einen Agent an, um mit ihm zu chatten oder ihm einen Auftrag zu geben. {name} kann ihm auch für dich Arbeit geben."},plugin:{title:"Verbinde eine App",ask:"Plugins verbinden {name} mit den Apps, die du nutzt: E-Mail, Kalender, Notizen, Smart Home und mehr.",explain:"Hier verbindest du deine Apps. Wähl eine, die du täglich nutzt, und klick auf Verbinden; dein Browser öffnet sich einmal zum Anmelden.",how:"Jede verbundene App wird ein neues Werkzeug für {name}. Danach fragst du einfach, zum Beispiel „Was steht morgen in meinem Kalender?“. Alles, was etwas sendet oder ändert, fragt dich trotzdem vorher."},ide:{title:"Lass Agents programmieren",ask:"Die Agentic IDE lässt Coding-Agents wie Claude Code und Codex in echten Terminals laufen, an deinen eigenen Projekten.",explain:"Das ist die Agentic IDE. Öffne einen Projektordner und starte in einem Fenster einen Coding-Agent.",how:"Jedes Fenster ist ein echtes Terminal mit eigenem Agent. Sprich mit ihnen per Tastatur oder per Stimme über {name}. Mehrere können nebeneinander am selben Projekt arbeiten."}}},t={first_run:e,app_tour:n,first_steps:i};export{n as app_tour,t as default,e as first_run,i as first_steps};
